"""`mac podcasts` — generated by tools/gen_groups.py from local-mac's podcasts__* handlers. Do not edit."""
import argparse

from mac.groups._backend import call, given


def register(registry):
    @registry.verb("podcasts", "list", mode="read",
                   desc='list all subscribed podcasts with episode counts')
    def podcasts_list(ns):
        return call('podcasts', 'list')

    def podcasts_episodes_args(p):
        p.add_argument('--podcast-title', default=argparse.SUPPRESS)
        p.add_argument('--podcast-uuid', default=argparse.SUPPRESS)
        p.add_argument('--unplayed', default=argparse.SUPPRESS, action="store_true")

    @registry.verb("podcasts", "episodes", mode="read",
                   desc='list episodes for a podcast. Provide podcast_title (partial match) or podcast_uuid', args=podcasts_episodes_args)
    def podcasts_episodes(ns):
        return call('podcasts', 'episodes', **given(ns, ('podcast_title', 'podcast_uuid', 'limit', 'unplayed')))

    def podcasts_recent_args(p):
        p.add_argument('--new-only', default=argparse.SUPPRESS, action="store_true")

    @registry.verb("podcasts", "recent", mode="read",
                   desc='list recent episodes across all podcasts. Set new_only=True for unheard episodes', args=podcasts_recent_args)
    def podcasts_recent(ns):
        return call('podcasts', 'recent', **given(ns, ('limit', 'new_only')))

    @registry.verb("podcasts", "in_progress", mode="read",
                   desc='list episodes that have been started but not finished (have a playhead position)')
    def podcasts_in_progress(ns):
        return call('podcasts', 'in_progress')
